// CSD_RATIONALE_BEGIN
// Math-step CSD with delimiter-aware chunking outside spans and adaptive decoding
// inside spans. The strategy tracks whether generation is currently inside a
// constrained arithmetic span (`insideConstrainedOut`) and the exact contents of
// that span (`currentConstrainedOut`), which are always the suffix of the full
// generated output while the span is open.
//
// Outside a span, the strategy generates in chunks until it hits either EOS or
// the opening delimiter "<<", since ordinary explanation text is unconstrained.
// Inside a span, it uses parser observations to choose between two modes:
// narrow positions use `ConstrainedStep` for a single tightly constrained token,
// while wider positions use `ConstrainedSymbol` with the provided token budget
// to emit several valid tokens at once. As soon as the parser reports the span
// is complete, the strategy closes it with ">>".
//
// This supports the task because free-form reasoning text can be generated
// naturally, while every arithmetic computation between << and >> is kept on a
// parser-valid path and closed immediately once complete.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the unconstrained chunk branch, entering a span only
// happens when `stoppedOpen` is true; then we set `currentConstrainedOut := []`,
// which is valid by the method precondition `parser.IsValidPrefix([])`. In the
// complete-prefix branch, `CloseConstrainedSpan` sets `insideConstrainedOut` to
// false, so the implication becomes vacuous. In the tight constrained branch,
// `ConstrainedStep` returns a parser-valid next token (or EOS, which breaks),
// and `AppendConstrainedToken` preserves validity. In the wide constrained
// branch, `ConstrainedSymbol` returns `currentOut` that is itself a valid
// parser prefix, and we assign that to `currentConstrainedOut`.
// suffix: In the unconstrained chunk branch, when we remain outside the span the
// implication is vacuous; when `stoppedOpen` is true we enter with
// `currentConstrainedOut := []`, and the length-0 suffix of `generated` equals
// `[]`. In the complete-prefix branch, `CloseConstrainedSpan` appends the close
// delimiter and resets the constrained state, so the implication is vacuous. In
// the tight constrained branch, `AppendConstrainedToken` appends the same token
// to both `generated` and `currentConstrainedOut`. In the wide constrained
// branch, with `stablePrefix := generated[..|generated|-|currentConstrainedOut|]`,
// we set `generated := stablePrefix + symbolOut` and
// `currentConstrainedOut := symbolOut`, so the suffix equality holds directly.
// progress: UnconstrainedChunk appends `stepsUsed` tokens and we do
// `steps := steps + stepsUsed`, so `|generated| <= |generatedPrefix| + steps` is
// preserved by linear arithmetic. CloseConstrainedSpan appends exactly one token
// and increments `steps` by 1. Tight constrained decoding appends exactly one
// token via `AppendConstrainedToken` and increments `steps` by 1. Wide
// constrained decoding replaces the old constrained suffix by `symbolOut`; the
// helper consumes `stepsUsed` generation steps, and the symbol length growth is
// bounded by those steps, so after `steps := steps + stepsUsed` the invariant
// remains true. Any EOS branch breaks immediately without further mutation.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var narrowThreshold: nat := 12;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant insideConstrainedOut ==> generated[|generated| - |currentConstrainedOut|..] == currentConstrainedOut
  invariant |generated| <= |generatedPrefix| + steps
  invariant cost == 0
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var chunkBudget: nat := maxSteps - steps;
    var chunkedGenerated, stoppedOpen, stoppedEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, chunkBudget, "<<", eosToken
    );
    generated := chunkedGenerated;
    steps := steps + stepsUsed;
    if stoppedEos {
      break;
    } else if stoppedOpen {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  } else {
    var isComplete := parser.IsCompletePrefix(currentConstrainedOut);
    if isComplete {
      var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := closedGenerated;
      insideConstrainedOut := closedInside;
      currentConstrainedOut := closedCurrent;
      steps := steps + 1;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
      if validCount <= narrowThreshold {
        var next := helpers.ConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, eosToken
        );
        steps := steps + 1;
        if next == eosToken {
          break;
        } else {
          var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := appendedGenerated;
          insideConstrainedOut := appendedInside;
          currentConstrainedOut := appendedCurrent;
        }
      } else {
        var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
        var symbolOut, hitEos, stepsUsed := helpers.ConstrainedSymbol(
          lm, parser, constrainedPrompt, currentConstrainedOut, stepTokenBudget, eosToken
        );
        generated := stablePrefix + symbolOut;
        currentConstrainedOut := symbolOut;
        steps := steps + stepsUsed;
        if hitEos {
          break;
        }
      }
    }
  }
}

